test('mud coverage matches native bytecode edge samples',()=>{
  for(const [u,v,amount,expected] of nativeFixtures){
    const actual=nativeMudMask([u,v],amount);
    assert.ok(Math.abs(actual-expected)<.00001,`native mask at ${u},${v},mud${amount}: ${actual} vs ${expected}`);
  }
});

test('native clean cutoff removes all splats',()=>{
  for(const amount of [0,.0001,.001])for(const uv of [[0,0],[.5516,.5628],[1,1]])assert.equal(nativeMudMask(uv,amount),0);
});

test('one original half-mud hit occludes the main splat centre',()=>{
  assert.equal(nativeMudMask([.5516,.5628],.5),1);
  assert.equal(nativeMudMask([0,0],.5),0);
});
